inline void DrawEmblem(cheeko::Display& d, int ox, int oy) {
  for (int i = 0; i < kEMBLEM_RUNS; ++i) {
    const uint16_t* r = kEMBLEM_RUN_DATA[i];
    d.FillRect(ox + r[1], oy + r[0], r[2], 1, kEMBLEM_PALETTE[r[3]]);
  }
}
